import unittest
from candidate import encode_shift, decode_shift

class TestEncodeShift(unittest.TestCase):
    def test_encode_shift_normalcase(self):
        self.assertEqual(encode_shift("abc"), "fgh")

    def test_encode_shift_empty_string(self):
        self.assertEqual(encode_shift(""), "")

    def test_encode_shift_single_character(self):
        self.assertEqual(encode_shift("a"), "f")

    def test_encode_shift_uppercase(self):
        self.assertEqual(encode_shift("ABC"), "DEF")

    def test_encode_shift_with_numbers(self):
        self.assertEqual(encode_shift("abc123"), "fgh123")

class TestDecodeShift(unittest.TestCase):
    def test_decode_shift_normalcase(self):
        self.assertEqual(decode_shift("fgh"), "abc")

    def test_decode_shift_empty_string(self):
        self.assertEqual(decode_shift(""), "")

    def test_decode_shift_single_character(self):
        self.assertEqual(decode_shift("f"), "a")

    def test_decode_shift_uppercase(self):
        self.assertEqual(decode_shift("DEF"), "ABC")

    def test_decode_shift_with_numbers(self):
        self.assertEqual(decode_shift("fgh123"), "abc123")

    def test_decode_shift_invalid_input(self):
        self.assertRaises(ValueError, decode_shift, "!@#$%^&*()")

if __name__ == '__main__':
    unittest.main()
